using System;
using System.Collections.Generic;
using Astrea.RunModifiers;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DiceReward", menuName = "Data/Rewards/DiceReward")]
public class DiceReward : Reward
{
	[Header("Dice Rewards")]
	[SerializeField]
	private DiceRewardSettings diceRewardSettings;

	[SerializeField]
	private DiceTier[] diceTiers;

	[SerializeField]
	private int amount;

	[SerializeField]
	private ListDiceEvent OnDiceRewardsGenerated;

	[SerializeField]
	private DicesRewardsListsList dicesRewardsListsList;

	[SerializeField]
	private bool removeDotAtTheEnd;

	[Header("Dice Reward Panel")]
	[SerializeField]
	private GameObject diceRewardPanelPrefab;

	[SerializeField]
	private GameObjectReference diceRewardPanelReference;

	[SerializeField]
	private GameObjectReference chestRewardPropGameObjectReference;

	[SerializeField]
	private MapHandler mapHandler;

	[NonSerialized]
	public List<Dice> JustShuffledDiceData = new List<Dice>();

	public DiceTier[] DiceTiers => diceTiers;

	public override string GetRewardName()
	{
		string text = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(rewardName);
		if (removeDotAtTheEnd)
		{
			text = text.RemoveLast();
		}
		return text;
	}

	public override void GetReward()
	{
		Debug.Log("-----------------GET DICE REWARD-----------------");
		if (diceRewardPanelReference.value == null)
		{
			JustShuffledDiceData.Clear();
		}
		int seedWithCurrentMapPlayerTrackerAndCurrentClearingRewardCount = mapHandler.GetSeedWithCurrentMapPlayerTrackerAndCurrentClearingRewardCount();
		if (JustShuffledDiceData.Count == 0)
		{
			RandomUtilities.SetUnityEngineRandomInitStateSeed(seedWithCurrentMapPlayerTrackerAndCurrentClearingRewardCount);
		}
		Action action = delegate
		{
			ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
			Debug.Log("-----------------openDiceRewardPanelAction-----------------");
			SpawnDiceRewardPanel();
			List<Dice> dice = GetDice(diceTiers, amount, shop: false);
			OnDiceRewardsGenerated.Raise(dice);
			JustShuffledDiceData = dice;
		};
		if (chestRewardPropGameObjectReference.value != null)
		{
			if (chestRewardPropGameObjectReference.value.activeInHierarchy)
			{
				if (!ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation)
				{
					Debug.Log("-----------------chestRewardPropGameObjectReference.value != null && chestRewardPropGameObjectReference.value.activeInHierarchy-----------------");
					chestRewardPropGameObjectReference.value.GetComponent<ChestRewardProp>().SetAfterAnimationAction(action);
				}
				else
				{
					action();
				}
			}
			else
			{
				Debug.Log("-----------------chestRewardPropGameObjectReference.value != null && !chestRewardPropGameObjectReference.value.activeInHierarchy-----------------");
				action();
			}
		}
		else
		{
			Debug.Log("-----------------chestRewardPropGameObjectReference.value == null");
			action();
		}
	}

	public void SpawnDiceRewardPanel()
	{
		if (diceRewardPanelReference.value == null)
		{
			diceRewardPanelReference.value = UnityEngine.Object.Instantiate(diceRewardPanelPrefab);
			diceRewardPanelReference.value.GetComponent<Canvas>().worldCamera = Camera.main;
		}
	}

	public List<Dice> GetDice(DiceTier[] diceTiers, int amount, bool shop)
	{
		List<Dice> diceList = new List<Dice>();
		int neutralAmount = 0;
		ForgottenKnowledgeRunModifier forgottenKnowledgeRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.ForgottenKnowledgeRunModifier;
		for (int i = 0; i < diceTiers.Length; i++)
		{
			List<Dice> anyDiceList = dicesRewardsListsList.GetAnyCharacterUnlockedDiceTierDiceList(diceTiers[i]).diceList.Duplicate();
			List<Dice> charDiceList = dicesRewardsListsList.GetCurrentCharacterUnlockedDiceTierDiceList(diceTiers[i]).diceList.Duplicate();
			for (int j = 0; j < JustShuffledDiceData.Count; j++)
			{
				anyDiceList.Remove(JustShuffledDiceData[j]);
				charDiceList.Remove(JustShuffledDiceData[j]);
			}
			RemoveCharactersAndChapterMutedDiceFromList(charDiceList);
			RemoveChapterMutedDiceFromList(anyDiceList);
			if (diceRewardSettings.PercentBasedDiceReward)
			{
				for (int k = 0; k < amount; k++)
				{
					Dice dicePicked;
					if (!shop && forgottenKnowledgeRunModifier != null)
					{
						if (forgottenKnowledgeRunModifier.GetNeutralAmount() == neutralAmount)
						{
							AddCharDiceToDiceList();
						}
						else
						{
							AddNeutralDiceToDiceList(ignoreNeutralAmountToCheck: true);
						}
					}
					else if (RandomUtilities.RandomChanceWithSeed(diceRewardSettings.SpecificCharDicePercentage))
					{
						AddCharDiceToDiceList();
					}
					else
					{
						AddNeutralDiceToDiceList(ignoreNeutralAmountToCheck: false);
					}
					void AddCharDiceToDiceList()
					{
						if (charDiceList.Count == 0)
						{
							dicePicked = anyDiceList.PopRandom();
							if (diceList.Contains(dicePicked))
							{
								anyDiceList.Remove(dicePicked);
								dicePicked = anyDiceList.PopRandom();
							}
							diceList.Add(dicePicked);
						}
						else
						{
							dicePicked = charDiceList.PopRandom();
							if (diceList.Contains(dicePicked))
							{
								charDiceList.Remove(dicePicked);
								dicePicked = charDiceList.PopRandom();
							}
							diceList.Add(dicePicked);
						}
					}
					void AddNeutralDiceToDiceList(bool ignoreNeutralAmountToCheck)
					{
						int num = (shop ? 1 : 2);
						if (neutralAmount == num && !ignoreNeutralAmountToCheck)
						{
							dicePicked = charDiceList.PopRandom();
							if (diceList.Contains(dicePicked))
							{
								charDiceList.Remove(dicePicked);
								dicePicked = charDiceList.PopRandom();
							}
							diceList.Add(dicePicked);
						}
						else
						{
							dicePicked = anyDiceList.PopRandom();
							if (diceList.Contains(dicePicked))
							{
								anyDiceList.Remove(dicePicked);
								dicePicked = anyDiceList.PopRandom();
							}
							diceList.Add(dicePicked);
							neutralAmount++;
						}
					}
				}
			}
			else
			{
				diceList.AddRange(anyDiceList);
				diceList.AddRange(charDiceList);
				diceList.PopRandom(amount);
			}
		}
		JustShuffledDiceData.Clear();
		diceList = ReferenceSingleton<MiscOmensHandler>.Instance.GetModifiedDiceOmenActions(diceList);
		diceList = ReferenceSingleton<RunModifiersManager>.Instance.GetModifiedDiceRunModifier(diceList);
		return diceList;
	}

	public void RemoveCharactersAndChapterMutedDiceFromList(List<Dice> diceList)
	{
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.name == "Austra" && ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.GetCharacterLevel() <= 1 && mapHandler.CurrentAreaIndex == 0)
		{
			diceList.RemoveAll((Dice die) => die.DiceName.Contains("Brilliance"));
			diceList.RemoveAll((Dice die) => die.DiceName.Contains("Confuse"));
			diceList.RemoveAll((Dice die) => die.DiceName.Contains("Aerial Needle"));
		}
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerCurrentOmens.PlayerHasBlessing("ArtisanStaffOmenData"))
		{
			diceList.RemoveAll((Dice die) => die.DiceName.Contains("Boosted Army"));
			diceList.RemoveAll((Dice die) => die.DiceName.Contains("Sparkling Repair"));
		}
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerCurrentOmens.PlayerHasBlessing("ContemplationSarcophagusOmenData"))
		{
			diceList.RemoveAll((Dice die) => die.DiceName.Contains("Inner Warmth"));
			if (!ReferenceSingleton<AssetsReference>.Instance.PlayerCurrentOmens.PlayerHasBlessing("FervorousSundialOmenData"))
			{
				diceList.RemoveAll((Dice die) => die.DiceName.Contains("Concentration"));
			}
		}
		RemoveChapterMutedDiceFromList(diceList);
	}

	private void RemoveChapterMutedDiceFromList(List<Dice> diceList)
	{
		if (!ReferenceSingleton<RunModifiersManager>.Instance.DraftDiceRunModifier || !ReferenceSingleton<RunModifiersManager>.Instance.DraftDiceRunModifier.IsTheChosenPool)
		{
			diceList.RemoveAll(delegate(Dice die)
			{
				PlayerDice playerDice = die as PlayerDice;
				return (mapHandler.IsOnAstreasHeart && playerDice.ChapterMute.Contains(3)) || playerDice.ChapterMute.Contains(mapHandler.CurrentAreaIndex + 1);
			});
		}
	}
}
